'use strict';
const header=document.querySelector('.header');
const updateHeader=()=>header.classList.toggle('scrolled',window.scrollY>12);
window.addEventListener('scroll',updateHeader,{passive:true});
updateHeader();
const {packages,maintenance,addons}=window.SITE_DATA;
const money=n=>'฿'+n.toLocaleString('th-TH');
const escapeHtml=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=features=>'<ul class="feature-list">'+features.map(f=>'<li>'+escapeHtml(f)+'</li>').join('')+'</ul>';
const fits=['สำหรับธุรกิจที่อยากมีตัวตนบนออนไลน์','สำหรับธุรกิจที่อยากจัดการเนื้อหาเอง','สำหรับร้านค้าที่พร้อมขายออนไลน์','สำหรับธุรกิจที่ขายผ่านทีม Sales'];
const highlights=[['สูงสุด 5 หน้า · 1 ภาษา','รองรับมือถือและทุกหน้าจอ','Contact form + LINE / โทร / Email','Google Maps','แก้ไข 2 รอบ · Deploy + ต่อ Domain'],['จัดการบทความและแค็ตตาล็อกสินค้า','หน้ารวมและหน้ารายละเอียด','ลงข้อมูล 5 บทความ + 10 สินค้า','ผู้ดูแล 1 บัญชี + คู่มือ CMS','รับประกันแก้บั๊ก 60 วัน'],['ตะกร้าสินค้า + Checkout','PromptPay QR ผ่าน Stripe','อัปเดตชำระเงินอัตโนมัติ','จัดการสต็อก สี / ไซซ์','คำสั่งซื้อ การจัดส่ง และอีเมล'],['ขอใบเสนอราคา (RFQ) หลายรายการ','เก็บ Lead และติดตามสถานะขาย','มอบหมาย Sales + นัดติดตาม','แจ้งเตือน Email / LINE OA','Manager Dashboard · 5 บัญชี']];
document.querySelector('#package-grid').innerHTML=packages.map((p,i)=>`<article class="package-card ${i===1?'featured':''}">${i===1?'<span class="tag">จัดการเนื้อหาเองได้</span>':''}<div class="card-top"><span class="package-number">PACKAGE / 0${i+1}</span><h3>${escapeHtml(p.name)}</h3><p class="fit">${fits[i]}</p><div class="price"><span class="currency">฿</span>${p.price.toLocaleString('th-TH')} <small>/ แพ็กเกจ</small></div></div><div class="card-content"><p class="inherit">${i===0?'พื้นฐานเว็บไซต์แนะนำธุรกิจ':i===1?'รวมขอบเขต Website Starter + CMS':'รวมขอบเขต Website CMS และเพิ่ม'}</p>${list(highlights[i])}<details class="details"><summary>ดูขอบเขตทั้งหมด (${p.features.length} รายการ)</summary>${p.notes.map(n=>'<p>'+escapeHtml(n)+'</p>').join('')}${list(p.features)}</details><button class="button ${i===1?'':'outline'}" data-choose="${i}">เลือกแพ็กเกจนี้ <span>↗</span></button></div></article>`).join('');
const comparison=[['เว็บไซต์ Responsive · 1 ภาษา',1,1,1,1],['Contact form + LINE / โทร / Email',1,1,1,1],['CMS บทความและแค็ตตาล็อกสินค้า',0,1,1,1],['ตะกร้า + Checkout + PromptPay QR',0,0,1,0],['ระบบสต็อกและจัดการคำสั่งซื้อ',0,0,1,0],['RFQ + Lead + ติดตามงานขาย',0,0,0,1],['Dashboard และสิทธิ์ Manager / Sales',0,0,0,1],['จำนวนบัญชีผู้ดูแล / ผู้ใช้','—','1','1','5'],['รับประกันแก้บั๊ก 60 วัน',0,1,1,1]];
document.querySelector('#compare-body').innerHTML=comparison.map(r=>'<tr><td>'+r[0]+'</td>'+r.slice(1).map(v=>typeof v==='number'?`<td class="${v?'yes':'no'}" aria-label="${v?'รวมในแพ็กเกจ':'ไม่รวมในแพ็กเกจ'}">${v?'✓':'—'}</td>`:'<td>'+v+'</td>').join('')+'</tr>').join('');
document.querySelector('#maintenance-grid').innerHTML=maintenance.map((p,i)=>`<article class="care-card"><span class="care-icon" aria-hidden="true">${['↻','◈','▦'][i]}</span><h3>${escapeHtml(p.name.replace('Maintenance for Website ','Website '))}</h3><div class="price">${money(p.price)} <small>/ ปี</small></div><p>บริการดูแลสำหรับแพ็กเกจนี้ · เลือกซื้อได้</p>${list(p.features.slice(0,4))}<details class="details"><summary>ดูการดูแลทั้งหมด (${p.features.length} รายการ)</summary>${list(p.features.slice(4))}</details></article>`).join('');
document.querySelector('#addons-list').innerHTML=addons.map((p,i)=>`<article class="addon-row"><span class="addon-icon" aria-hidden="true">${['✦','⇄','▤'][i]}</span><div><h3>${escapeHtml(p.name)}</h3><span class="compatibility">${escapeHtml(p.notes.join(' '))}</span></div>${list(p.features)}<div class="price">${money(p.price)}<small>จ่ายครั้งเดียว</small></div></article>`).join('');
const select=document.querySelector('#package-select'),care=document.querySelector('#care-check');
select.innerHTML=packages.map((p,i)=>`<option value="${i}">${p.name} — ${money(p.price)}</option>`).join('');
const compatible=i=>i===0?[]:i===1?[0]:i===2?[0,1]:[0,2];
let addonSelection=new Set();
function updateTotal(){const i=Number(select.value);const chosen=[...document.querySelectorAll('[data-addon]:checked')].map(e=>Number(e.dataset.addon));addonSelection=new Set(chosen);const yearly=i>0&&care.checked?maintenance[i-1].price:0;const total=packages[i].price+yearly+chosen.reduce((s,a)=>s+addons[a].price,0);document.querySelector('#total').textContent=money(total);document.querySelector('#renewal').textContent=yearly?money(yearly)+'/ปี':'ไม่ได้เลือก';document.querySelector('#copy-status').textContent='';}
function updateOptions(){const i=Number(select.value);care.disabled=i===0;if(i===0)care.checked=false;document.querySelector('#care-label').textContent=i===0?'ไม่มีบริการดูแลรายปีในแพ็กเกจ Starter':`เพิ่มบริการดูแล ${packages[i].name} — ${money(maintenance[i-1].price)}/ปี`;care.closest('label').classList.toggle('disabled',i===0);document.querySelector('#addon-options').innerHTML=compatible(i).map(a=>`<label class="check-row"><input type="checkbox" data-addon="${a}" ${addonSelection.has(a)?'checked':''}><span>${addons[a].name} — ${money(addons[a].price)}</span></label>`).join('')||'<p class="check-row disabled">ไม่มีบริการเสริมที่รองรับแพ็กเกจ Starter</p>';updateTotal();}
select.addEventListener('change',updateOptions);care.addEventListener('change',updateTotal);document.querySelector('#addon-options').addEventListener('change',updateTotal);updateOptions();
document.querySelectorAll('[data-choose]').forEach(b=>b.addEventListener('click',()=>{select.value=b.dataset.choose;updateOptions();document.querySelector('#estimate').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}));
document.querySelector('#copy-estimate').addEventListener('click',async()=>{const i=Number(select.value),chosen=[...addonSelection];const message=`สวัสดีครับ/ค่ะ สนใจทำเว็บไซต์กับ Genius Picture\nแพ็กเกจ: ${packages[i].name} ${money(packages[i].price)}\nบริการดูแลรายปี: ${i>0&&care.checked?money(maintenance[i-1].price)+'/ปี':'ไม่เลือก'}\nบริการเสริม: ${chosen.length?chosen.map(a=>addons[a].name+' '+money(addons[a].price)).join(', '):'ไม่เลือก'}\nงบรวมปีแรกเบื้องต้น: ${document.querySelector('#total').textContent}\nต้องการปรึกษาขอบเขตงานและใบเสนอราคาเพิ่มเติม`;const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText(message);status.innerHTML='คัดลอกแล้ว · <a href="https://line.me/R/ti/p/@Genisolu" target="_blank" rel="noopener">เปิด LINE แล้ววางข้อความเพื่อคุยกับเรา ↗</a>';}catch{status.textContent='เลือกและคัดลอกข้อความด้านล่าง แล้วส่งทาง LINE @Genisolu';let area=document.querySelector('#manual-copy');if(!area){area=document.createElement('textarea');area.id='manual-copy';area.setAttribute('aria-label','ข้อความแพ็กเกจสำหรับคัดลอก');area.style.cssText='width:100%;height:170px;padding:12px;margin-top:12px;border:1px solid #bfd9cc;border-radius:7px;font:inherit;font-size:12px';status.after(area);}area.value=message;area.focus();area.select();}});
const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'ปิดเมนู':'เปิดเมนู');});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','เปิดเมนู');}));
